pecas.css:
@keyframes aqua-watercolor-shift {
  0% { background-position: 0% 50%; }
  50% { background-position: 100% 50%; }
  100% { background-position: 0% 50%; }
}
.aqua-hero-strip {
  display: flex;
  justify-content: center;
  padding: 14px 26px;
  margin: 0 auto 8px;
  max-width: fit-content;
  border-radius: 50rem;
  border: 2px solid var(--aqua-primary);
  background: linear-gradient(-45deg, #fdfcfb, #e2d1c3, #f5f7fa, #c3cfe2, #e0c3fc, #fbc2eb);
  background-size: 400% 400%;
  animation: aqua-watercolor-shift 15s ease infinite;
}
.aqua-hero-strip-tag {
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.3px;
  background: linear-gradient(to right, #ff7eb3, #ff758c, #ff7eb3, #7afcff, #feff9c, #ff7eb3);
  background-size: 200% auto;
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  animation: aqua-watercolor-shift 5s linear infinite;
}

