@keyframes aqua-splash-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}
.aqua-hero-strip--splash {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 12px 24px 12px 18px;
  margin: 0 auto 8px;
  max-width: fit-content;
  border-radius: 255px 15px 225px 15px / 15px 225px 15px 255px;
  background: linear-gradient(135deg, #fce4ec, #e0f7fa, #fff9c4);
  border: 2px solid var(--aqua-primary);
  animation: aqua-splash-pulse 3.5s ease-in-out infinite;
}
.aqua-hero-strip-icon {
  font-size: 1.1rem;
  line-height: 1;
}
.aqua-hero-strip--splash .aqua-hero-strip-tag {
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.3px;
  color: var(--aqua-primary);
}

@keyframes aqua-underline-shift {
  0% { background-position: 0% 50%; }
  100% { background-position: 200% 50%; }
}
.aqua-hero-strip--underline {
  display: flex;
  justify-content: center;
  padding: 4px 6px 10px;
  margin: 0 auto 8px;
  max-width: fit-content;
  background-image: linear-gradient(to right, #ff7eb3, #7afcff, #feff9c, #ff7eb3);
  background-size: 200% 4px;
  background-repeat: no-repeat;
  background-position: 0 100%;
  animation: aqua-underline-shift 4s linear infinite;
}
.aqua-hero-strip--underline .aqua-hero-strip-tag {
  font-size: 0.95rem;
  font-weight: 800;
  letter-spacing: 0.4px;
  text-transform: uppercase;
  color: var(--aqua-primary);
}

@keyframes aqua-drop-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(0,0,0,0); }
  50% { box-shadow: 0 0 10px 2px rgba(230,126,34,0.35); }
}
.aqua-hero-strip--droplets {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 22px;
  margin: 0 auto 8px;
  max-width: fit-content;
  border-radius: 50rem;
  background: #fdfcfb;
  border: 1px solid var(--aqua-accent);
}
.aqua-hero-strip-drop {
  width: 10px;
  height: 10px;
  border-radius: 50% 50% 50% 0;
  transform: rotate(45deg);
  background: radial-gradient(circle at 30% 30%, #ff7eb3, #7afcff);
  animation: aqua-drop-glow 2.4s ease-in-out infinite;
}
.aqua-hero-strip--droplets .aqua-hero-strip-tag {
  font-size: 0.92rem;
  font-weight: 700;
  color: var(--aqua-accent);
}

.aqua-hero-strip--framed {
  display: flex;
  justify-content: center;
  padding: 12px 28px;
  margin: 0 auto 8px;
  max-width: fit-content;
  clip-path: polygon(12px 0, 100% 0, 100% calc(100% - 12px), calc(100% - 12px) 100%, 0 100%, 0 12px);
  background: linear-gradient(#fdfcfb, #fdfcfb) padding-box,
              linear-gradient(120deg, #e0c3fc, #8ec5fc, #ffd3a5) border-box;
  border: 2px solid transparent;
}
.aqua-hero-strip--framed .aqua-hero-strip-tag {
  font-size: 0.9rem;
  font-weight: 800;
  letter-spacing: 1px;
  text-transform: uppercase;
  font-variant: small-caps;
  color: var(--aqua-primary);
}

pecas.css:
.contact-form-widget { max-width: 100%; }
.contact-form-name, .contact-form-email, .contact-form-email-message {
  width: 100% !important;
  max-width: 100% !important;
  padding: 15px;
  margin-bottom: 15px;
  border: 1px solid #ddd;
  border-radius: 8px;
  font-family: inherit;
}
.contact-form-button {
  width: 100%;
  padding: 15px;
  background-color: var(--aqua-accent);
  color: white;
  border: none;
  border-radius: 8px;
  font-weight: bold;
  cursor: pointer;
}
